    <script>
        // ============== CHIP-8 EMULATOR ==============
        const MEMORY_SIZE = 4096;
        const SCREEN_WIDTH = 64;
        const SCREEN_HEIGHT = 32;
        const FONT_SET_START = 0x050;
        const PROGRAM_START = 0x200;

        // Font set: 5x8 binary patterns for 0-F
        const FONT_SET = [
            0xF0, 0x90, 0x90, 0x90, 0xF0, // 0
            0x20, 0x60, 0x20, 0x20, 0x70, // 1
            0xF0, 0x10, 0xF0, 0x80, 0xF0, // 2
            0xF0, 0x10, 0xF0, 0x10, 0xF0, // 3
            0x90, 0x90, 0xF0, 0x10, 0x10, // 4
            0xF0, 0x80, 0xF0, 0x10, 0xF0, // 5
            0xF0, 0x80, 0xF0, 0x90, 0xF0, // 6
            0xF0, 0x10, 0x20, 0x40, 0x40, // 7
            0xF0, 0x90, 0xF0, 0x90, 0xF0, // 8
            0xF0, 0x90, 0xF0, 0x10, 0xF0, // 9
            0xF0, 0x90, 0xF0, 0x90, 0x90, // A
            0xE0, 0x90, 0xE0, 0x90, 0xE0, // B
            0xF0, 0x80, 0x80, 0x80, 0xF0, // C
            0xE0, 0x90, 0x90, 0x90, 0xE0, // D
            0xF0, 0x80, 0xF0, 0x80, 0xF0, // E
            0xF0, 0x80, 0xF0, 0x80, 0x80  // F
        ];

        // Keypad layout: 0x0 to 0xF
        const KEY_NAMES = [
            '1', '2', '3', 'C', '4', '5', '6', 'D', '7', '8', '9', 'E', 'A', '0', 'B', 'F'
        ];

        // ============== STATE ==============
        let memory = new Uint8Array(MEMORY_SIZE);
        let registers = new Uint8Array(16); // V0-VF
        let I = 0;
        let PC = PROGRAM_START;
        let stack = [];
        let delayTimer = 0;
        let soundTimer = 0;
        let display = new Uint8Array(SCREEN_WIDTH * SCREEN_HEIGHT);
        let keyState = new Uint8Array(16); // 0 = released, 1 = pressed
        let paused = true;
        let speed = 10; // instructions per frame
        let lastFrameTime = 0;
        let running = false;

        // ============== DISPLAY ==============
        const canvas = document.getElementById('display');
        const ctx = canvas.getContext('2d');
        const imageData = ctx.createImageData(SCREEN_WIDTH, SCREEN_HEIGHT);
        const pixelData = imageData.data;

        function clearDisplay() {
            display.fill(0);
        }

        function drawPixel(x, y, set) {
            if (x >= SCREEN_WIDTH || y >= SCREEN_HEIGHT) return;
            const idx = y * SCREEN_WIDTH + x;
            if (set) {
                display[idx] = 1;
            } else {
                display[idx] = 0;
            }
        }

        function renderDisplay() {
            pixelData.fill(0);
            for (let y = 0; y < SCREEN_HEIGHT; y++) {
                for (let x = 0; x < SCREEN_WIDTH; x++) {
                    const idx = y * SCREEN_WIDTH + x;
                    if (display[idx]) {
                        const pidx = idx * 4;
                        pixelData[pidx] = 255;
                        pixelData[pidx + 1] = 255;
                        pixelData[pidx + 2] = 255;
                        pixelData[pidx + 3] = 255;
                    }
                }
            }
            ctx.putImageData(imageData, 0, 0);
        }

        // ============== SPRITE ==============
        function drawSprite(x, y, n, register) {
            const sprite = memory.subarray(I, I + n);
            let collision = 0;
            for (let row = 0; row < n; row++) {
                for (let bit = 0; bit < 8; bit++) {
                    const px = (x + bit) % SCREEN_WIDTH;
                    const py = (y + row) % SCREEN_HEIGHT;
                    const spriteBit = (sprite[row] >> (7 - bit)) & 1;
                    const displayIdx = py * SCREEN_WIDTH + px;
                    const old = display[displayIdx];
                    if (spriteBit) {
                        display[displayIdx] = old ? 0 : 1;
                        if (old) collision = 1;
                    }
                }
            }
            registers[0xF] = collision;
        }

        // ============== KEYBOARD ==============
        function initKeyboard() {
            const keys = document.querySelectorAll('.key');
            keys.forEach(el => {
                const key = el.getAttribute('data-key');
                const chip8Key = KEY_NAMES.indexOf(key);
                if (chip8Key === -1) return;

                el.addEventListener('keydown', (e) => {
                    e.preventDefault();
                    keyState[chip8Key] = 1;
                    el.classList.add('active');
                });

                el.addEventListener('keyup', (e) => {
                    e.preventDefault();
                    keyState[chip8Key] = 0;
                    el.classList.remove('active');
                });
            });

            window.addEventListener('keydown', (e) => {
                const chip8Key = KEY_NAMES.indexOf(e.key);
                if (chip8Key !== -1) {
                    keyState[chip8Key] = 1;
                    const el = document.querySelector(`.key[data-key="${e.key}"]`);
                    if (el) el.classList.add('active');
                }
            });

            window.addEventListener('keyup', (e) => {
                const chip8Key = KEY_NAMES.indexOf(e.key);
                if (chip8Key !== -1) {
                    keyState[chip8Key] = 0;
                    const el = document.querySelector(`.key[data-key="${e.key}"]`);
                    if (el) el.classList.remove('active');
                }
            });
        }

        // ============== CPU ==============
        function reset() {
            memory.fill(0);
            registers.fill(0);
            I = 0;
            PC = PROGRAM_START;
            stack = [];
            delayTimer = 0;
            soundTimer = 0;
            clearDisplay();
            paused = true;
            running = false;
            document.getElementById('status').textContent = 'Reset';
        }

        function loadFontSet() {
            for (let i = 0; i < FONT_SET.length; i++) {
                memory[FONT_SET_START + i] = FONT_SET[i];
            }
        }

        function fetchOpcode() {
            return (memory[PC] << 8) | memory[PC + 1];
        }

        function decodeAndExecute() {
            const opcode = fetchOpcode();
            const highNibble = (opcode & 0xF000) >> 12;
            const x = (opcode & 0x0F00) >> 8;
            const y = (opcode & 0x00F0) >> 4;
            const nn = opcode & 0x00FF;
            const nnn = opcode & 0x0FFF;

            switch (highNibble) {
                case 0x0:
                    switch (opcode) {
                        case 0x00E0: clearDisplay(); PC += 2; break;
                        case 0x00EE: PC = stack.pop(); break;
                        default: PC += 2;
                    }
                    break;

                case 0x1:
                    PC = nnn;
                    break;

                case 0x2:
                    stack.push(PC);
                    PC = nnn;
                    break;

                case 0x3:
                    if (registers[x] === nn) PC += 4;
                    else PC += 2;
                    break;

                case 0x4:
                    if (registers[x] !== nn) PC += 4;
                    else PC += 2;
                    break;

                case 0x5:
                    if (registers[x] === registers[y]) PC += 4;
                    else PC += 2;
                    break;

                case 0x6:
                    registers[x] = nn;
                    PC += 2;
                    break;

                case 0x7:
                    registers[x] = (registers[x] + nn) & 0xFF;
                    PC += 2;
                    break;

                case 0x8:
                    switch (nn) {
                        case 0x0:
                            registers[x] = registers[y];
                            break;
                        case 0x1:
                            registers[x] = registers[x] | registers[y];
                            registers[0xF] = (registers[x] & registers[y]) ? 1 : 0;
                            break;
                        case 0x2:
                            registers[x] = registers[x] & ~registers[y];
                            registers[0xF] = (registers[x] & registers[y]) ? 0 : 1;
                            break;
                        case 0x3:
                            registers[x] = registers[x] ^ registers[y];
                            registers[0xF] = (registers[x] & registers[y]) ? 1 : 0;
                            break;
                        case 0x4:
                            const sum = registers[x] + registers[y];
                            registers[0xF] = sum > 0xFF ? 1 : 0;
                            registers[x] = sum & 0xFF;
                            break;
                        case 0x5:
                            registers[0xF] = registers[x] > registers[y] ? 1 : 0;
                            registers[x] = (registers[x] - registers[y]) & 0xFF;
                            break;
                        case 0x6:
                            registers[0xF] = registers[y] & 1;
                            registers[x] = registers[y] >> 1;
                            break;
                        case 0x7:
                            registers[0xF] = registers[y] > registers[x] ? 1 : 0;
                            registers[x] = (registers[y] - registers[x]) & 0xFF;
                            break;
                        case 0xE:
                            registers[0xF] = (registers[y] >> 7) & 1;
                            registers[x] = (registers[y] << 1) & 0xFF;
                            break;
                    }
                    PC += 2;
                    break;

                case 0x9:
                    if (registers[x] !== registers[y]) PC += 4;
                    else PC += 2;
                    break;

                case 0xA:
                    I = nnn;
                    PC += 2;
                    break;

                case 0xB:
                    PC = nnn + registers[0];
                    break;

                case 0xC:
                    registers[x] = Math.floor(Math.random() * 256) & nn;
                    PC += 2;
                    break;

                case 0xD:
                    drawSprite(registers[x], registers[y], nn, x);
                    PC += 2;
                    break;

                case 0xE:
                    switch (nn) {
                        case 0x9E:
                            if (keyState[registers[x]]) PC += 4;
                            else PC += 2;
                            break;
                        case 0xA1:
                            if (!keyState[registers[x]]) PC += 4;
                            else PC += 2;
                            break;
                    }
                    break;

                case 0xF:
                    switch (nn) {
                        case 0x07:
                            registers[x] = delayTimer;
                            PC += 2;
                            break;
                        case 0x0A:
                            // Wait for key press
                            for (let k = 0; k < 16; k++) {
                                if (keyState[k]) {
                                    registers[x] = k;
                                    PC += 2;
                                    return;
                                }
                            }
                            return;
                        case 0x15:
                            delayTimer = registers[x];
                            PC += 2;
                            break;
                        case 0x18:
                            soundTimer = registers[x];
                            PC += 2;
                            break;
                        case 0x1E:
                            I = (I + registers[x]) & 0xFFF;
                            PC += 2;
                            break;
                        case 0x29:
                            I = FONT_SET_START + (registers[x] & 0xF) * 5;
                            PC += 2;
                            break;
                        case 0x33:
                            memory[I] = Math.floor(registers[x] / 100);
                            memory[I + 1] = Math.floor((registers[x] % 100) / 10);
                            memory[I + 2] = registers[x] % 10;
                            PC += 2;
                            break;
                        case 0x55:
                            for (let k = 0; k <= x; k++) {
                                memory[I + k] = registers[k];
                            }
                            I = (I + x + 1) & 0xFFF;
                            PC += 2;
                            break;
                        case 0x65:
                            for (let k = 0; k <= x; k++) {
                                registers[k] = memory[I + k];
                            }
                            I = (I + x + 1) & 0xFFF;
                            PC += 2;
                            break;
                    }
                    break;

                default:
                    PC += 2;
            }
        }

        function updateTimers() {
            if (delayTimer > 0) delayTimer--;
            if (soundTimer > 0) soundTimer--;
        }

        function updateDebugger() {
            document.getElementById('reg-v07').textContent =
                Array.from(registers.slice(0, 8)).map(v => 'V' + v.toString(16).padStart(2, '0')).join(' ');
            document.getElementById('reg-v8f').textContent =
                Array.from(registers.slice(8, 16)).map(v => 'V' + v.toString(16).padStart(2, '0')).join(' ');
            document.getElementById('reg-i').textContent = '0x' + I.toString(16).padStart(3, '0').toUpperCase();
            document.getElementById('reg-pc').textContent = '0x' + PC.toString(16).padStart(3, '0').toUpperCase();
            document.getElementById('reg-stack').textContent =
                '[' + stack.map(n => '0x' + n.toString(16).padStart(3, '0').toUpperCase()).join(', ') + ']';
            document.getElementById('reg-delay').textContent = delayTimer;
            document.getElementById('reg-sound').textContent = soundTimer;

            const opcode = fetchOpcode();
            const high = (opcode & 0xF000) >> 12;
            const x = (opcode & 0x0F00) >> 8;
            const y = (opcode & 0x00F0) >> 4;
            const nn = opcode & 0x00FF;
            const nnn = opcode & 0x0FFF;
            let mnemonic = 'UNKNOWN';
            if (high === 0) {
                mnemonic = opcode === 0x00E0 ? 'CLS' : opcode === 0x00EE ? 'RET' : 'SYS';
            } else if (high === 1) mnemonic = 'JP';
            else if (high === 2) mnemonic = 'CALL';
            else if (high === 3) mnemonic = 'SE';
            else if (high === 4) mnemonic = 'SNE';
            else if (high === 5) mnemonic = 'SE_VX_VY';
            else if (high === 6) mnemonic = 'LD_VX';
            else if (high === 7) mnemonic = 'ADD_VX';
            else if (high === 8) mnemonic = 'ALU_VX_VY';
            else if (high === 9) mnemonic = 'SNE_VX_VY';
            else if (high === 0xA) mnemonic = 'LD_I';
            else if (high === 0xB) mnemonic = 'JP_V0';
            else if (high === 0xC) mnemonic = 'RND';
            else if (high === 0xD) mnemonic = 'DRW';
            else if (high === 0xE) mnemonic = 'SKP';
            else if (high === 0xF) mnemonic = 'LD';

            const opStr = mnemonic.padEnd(6) + ' 0x' + opcode.toString(16).padStart(4, '0').toUpperCase();
            document.getElementById('instruction').textContent = opStr;
        }

        function gameLoop(timestamp) {
            if (!lastFrameTime) lastFrameTime = timestamp;
            const elapsed = timestamp - lastFrameTime;

            if (!paused && running) {
                if (elapsed >= (1000 / 60)) {
                    lastFrameTime = timestamp;
                    for (let i = 0; i < speed; i++) {
                        decodeAndExecute();
                    }
                    updateTimers();
                    renderDisplay();
                    updateDebugger();
                }
            } else {
                // Still update display in pause mode to show sprite changes
                if (elapsed >= 100) {
                    lastFrameTime = timestamp;
                    renderDisplay();
                    updateDebugger();
                }
            }

            requestAnimationFrame(gameLoop);
        }

        // ============== UI ==============
        document.getElementById('btn-run').addEventListener('click', () => {
            paused = false;
            running = true;
            document.getElementById('status').textContent = 'Running';
        });

        document.getElementById('btn-pause').addEventListener('click', () => {
            paused = true;
            running = false;
            document.getElementById('status').textContent = 'Paused';
        });

        document.getElementById('btn-step').addEventListener('click', () => {
            paused = false;
            running = false;
            decodeAndExecute();
            updateTimers();
            renderDisplay();
            updateDebugger();
            document.getElementById('status').textContent = 'Stepped';
        });

        document.getElementById('btn-reset').addEventListener('click', reset);

        document.getElementById('speed').addEventListener('input', (e) => {
            speed = parseInt(e.target.value);
            document.getElementById('speed-val').textContent = speed + ' I/帧';
        });

        document.getElementById('btn-demo').addEventListener('click', loadDemoROM);

        document.getElementById('rom-file').addEventListener('change', (e) => {
            const file = e.target.files[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (evt) => {
                const bytes = new Uint8Array(evt.target.result);
                for (let i = 0; i < bytes.length; i++) {
                    memory[PROGRAM_START + i] = bytes[i];
                }
                reset();
                running = true;
                paused = false;
                document.getElementById('status').textContent = 'Running (loaded file)';
            };
            reader.readAsArrayBuffer(file);
        });

        // ============== DEMO ROM ==============
        function loadDemoROM() {
            reset();
            loadFontSet();

            // Simple CHIP-8 demo: draw a sprite and react to key press
            const demoBytes = new Uint8Array([
                0xA2, 0x00, // LD V2, 0x00
                0xA3, 0x01, // LD V3, 0x01
                0xA4, 0x02, // LD V4, 0x02
                0xA5, 0x03, // LD V5, 0x03
                0x6A, 0x10, // LD V10, 0x10
                0x6B, 0x20, // LD V11, 0x20
                0x6C, 0x30, // LD V12, 0x30
                0x6D, 0x40, // LD V13, 0x40
                0x6E, 0x50, // LD V14, 0x50
                0x6F, 0x60, // LD V15, 0x60
                // Draw a 4x4 sprite at (10, 10)
                0x6A, 0x0A, // LD V10, 0x0A
                0x6B, 0x0A, // LD V11, 0x0A
                0x6C, 0x04, // LD V12, 0x04
                0xD0, 0x04, // DRW V10, V11, V12
                // Wait for key press (key 0x1 = '1')
                0xF0, 0x0A, // LD V0, K
                0x3F, 0x01, // SE V0, 0x01
                0x6F, 0xFF, // LD V15, 0xFF
                0x6F, 0x00, // LD V15, 0x00
                0x12, 0x00, // JP 0x0200
                // Sprite data (4x8)
                0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80,
                0x80, 0x40, 0x20, 0x10, 0x08, 0x04, 0x02, 0x01,
                0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
